-- =============================================================================
-- busan-private-car-charter-city-tour — NEW product (tour_product v2)
-- =============================================================================
-- Generated 2026-08-07. Regenerate with:
--   node scripts/gen-busan-city-charter-sql-2026-08.mjs
--
-- Owner instruction 2026-08-07: Busan had a cruise-port private charter but no
-- city one. Its own pickup notes even pointed guests at "our separate private
-- Busan day-charter", which did not exist. This is that product.
--
-- Recommended routes are IMPORTED at build time from the three Busan tours the
-- owner named (top-attractions, small-group Sky Capsule, cruise-shore coastal),
-- per locale, plus a fourth custom-route drawer. See
-- scripts/build-busan-city-charter-2026-08.mjs.
--
-- 🔴 price_type = 'vehicle'. /api/bookings multiplies the unit price by guest
-- count only when price_type is 'person'. Getting this wrong would bill a
-- family of five five times for one car.
--
-- Rate card (owner, converted at 1,423.48 KRW/USD, rounded to the nearest $5):
--   5h ₩230,000→$160 · 6h ₩260,000→$185 · 7h ₩290,000→$205
--   8h ₩320,000→$225 · 9h ₩360,000→$255      1–7 pax; 8+ pax = 2x (second car)
--   Gimhae Airport pickup or drop-off ₩50,000→$35 · Gyeongju ₩80,000→$55
--   each hour past 9h ₩50,000→$35
-- tours.price is the cheapest cell, because the rate card is what gets charged
-- (lib/tour-product/charterRateCard.ts, owner decision the same day).
--
-- Idempotent: tours ON CONFLICT (slug); tour_product_pages ON CONFLICT (slug, locale);
--             offer insert-if-absent.
-- AFTER APPLYING: node scripts/import-match-v18.mjs --single busan-private-car-charter-city-tour
-- Web: /tour-product/busan-private-car-charter-city-tour
-- =============================================================================

BEGIN;

-- 1) tours — booking + /tour/[id] checkout
INSERT INTO public.tours (
  title, slug, city, tag, subtitle, description, highlight, price, original_price, price_currency, price_type, image_url, gallery_images, duration, difficulty, group_size, lunch_included, ticket_included, pickup_info, notes, badges, highlights, includes, excludes, schedule, itinerary_details, faqs, rating, review_count, pickup_points_count, dropoff_points_count, is_active, is_featured, translations, seo_title, meta_description
) VALUES (
  'Busan Private Car Charter',
  'busan-private-car-charter-city-tour',
  'Busan',
  'Private charter · Busan city',
  'Build your own Busan day with a private licensed driver-guide, picked up at your hotel and priced by the hour.',
  'A private car and licensed driver-guide for your group alone, anywhere in Busan. Start from one of three recommended routes — the classic top-attractions day, the sea temple and Sky Capsule coast, or the old-downtown and Songdo loop — then move, drop or add stops until the day is yours. Hotel pickup included, 5 to 9 hours, one price per vehicle for up to 7 guests.',
  'Build your own Busan day with a private licensed driver-guide, picked up at your hotel and priced by the hour.',
  160,
  NULL,
  'USD',
  'vehicle',
  'https://www.atockorea.com/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp',
  '["https://www.atockorea.com/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","https://www.atockorea.com/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","https://www.atockorea.com/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","https://www.atockorea.com/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","https://www.atockorea.com/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"]'::jsonb,
  '5–9 hours',
  'Easy',
  'Private (1–7 per vehicle)',
  FALSE,
  FALSE,
  'Door-to-door pickup at your accommodation anywhere in central Busan (Seomyeon, Haeundae, Nampo-dong, Busan Station and surrounding districts) at a start time you choose. Drop-off anywhere in Busan. Gimhae International Airport pickup or drop-off is a paid add-on.',
  'Sold by the hour and priced per vehicle, not per person: 5h US$160 / 6h US$185 / 7h US$205 / 8h US$225 / 9h US$255 for 1-7 guests. 8 or more guests travel in two vehicles at twice the rate. Add-ons: Gimhae Airport pickup or drop-off +US$35, a Gyeongju day +US$55, each hour past 9 +US$35. Entrance fees, ride tickets (including the Sky Capsule) and meals are paid directly at the stops you choose.',
  '["Private Tour","Fully Customizable","Busan Hotel Pickup"]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[{"time":"Best in 8–9 hours","title":"Route 1: Busan Top Attractions","description":"Sea temple, coastal park, memorial, painted village, fish market"},{"time":"Best in 8 hours","title":"Route 2: Sea Temple, Sky Capsule & Culture Villages","description":"Sea temple, glass skywalk, Sky Capsule, beach, two mural villages"},{"time":"Best in 8–9 hours","title":"Route 3: Coast and Old Downtown","description":"Sea temple, memorial, three markets, painted village, two Songdo viewpoints, city tower"},{"time":"Any of the 5–9 hour options","title":"Route 4: Build your own day","description":"Your stops, your order, your pace"}]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  0,
  0,
  1,
  1,
  TRUE,
  FALSE,
  '{}'::jsonb,
  'Busan Private Car Charter with Driver (5–9 hours) | AtoC Korea',
  'Private car charter in Busan with a licensed English-speaking driver-guide and hotel pickup. Choose from three recommended routes or build your own. 5 to 9 hours, one price per vehicle for up to 7 guests, Gimhae Airport and Gyeongju add-ons available.'
)
