) VALUES (
  'busan-private-car-charter-city-tour',
  'ko',
  'busan-private-car-charter-city-tour',
  TRUE,
  1,
  '부산 프라이빗 차량 전세',
  '숙소로 모시러 가는 전용 차량과 자격증 있는 기사 가이드로, 시간 단위 요금으로 부산 하루를 직접 짭니다.',
  '부산 (시내 + 해안)',
  '5~9시간',
  4,
  0,
  0,
  ARRAY['프라이빗 투어', '일정 자유 변경', '부산 숙소 픽업']::text[],
  '/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp',
  '/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp',
  '일행만 타는 전용 차량과 자격증 있는 기사 가이드가 부산 어디든 함께합니다. 추천 코스 세 가지 — 대표 명소를 도는 클래식 코스, 해동 용궁사와 스카이캡슐의 해안 코스, 원도심과 송도를 잇는 코스 — 중 하나로 시작해 스톱을 옮기고 빼고 더하면 그날은 일행의 하루가 됩니다. 숙소 픽업 포함, 5~9시간, 7인까지 차량당 한 가격.',
  '부산 프라이빗 차량 전세 (5~9시간) | AtoC Korea',
  '영어 가능한 자격증 기사 가이드와 숙소 픽업이 포함된 부산 프라이빗 차량 전세. 추천 코스 세 가지 중 선택하거나 직접 일정을 짤 수 있습니다. 5~9시간, 7인까지 차량당 한 가격, 김해공항·경주 옵션 추가 가능.',
  '부산 시내',
  '프라이빗 차량 전세',
  '160',
  'USD',
  'vehicle',
  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"busan-private-car-charter-city-tour","locale":"ko","product_id":"busan-private-car-charter-city-tour","seo":{"pageTitle":"부산 프라이빗 차량 전세 (5~9시간) | AtoC Korea","metaDescription":"영어 가능한 자격증 기사 가이드와 숙소 픽업이 포함된 부산 프라이빗 차량 전세. 추천 코스 세 가지 중 선택하거나 직접 일정을 짤 수 있습니다. 5~9시간, 7인까지 차량당 한 가격, 김해공항·경주 옵션 추가 가능.","title":"부산 프라이빗 차량 전세 (기사 가이드 동행) | AtoC Korea","description":"숙소 픽업과 자격증 기사 가이드가 포함된 부산 시간제 프라이빗 차량 전세. 실제로 운행 중인 부산 투어 세 개의 일정을 그대로 가져와 추천 코스로 제공하고, 원하는 대로 바꿀 수 있습니다.","primaryKeywords":["부산 프라이빗 차량 전세","부산 프라이빗 투어","부산 숙소 픽업 투어","부산 기사 가이드 대절","부산 경주 프라이빗 차량"],"ogImage":"https://www.atockorea.com/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"},"catalog_card":{"slug":"busan-private-car-charter-city-tour","title":"부산 프라이빗 차량 전세","subtitle":"숙소로 모시러 가는 전용 차량과 자격증 있는 기사 가이드로, 시간 단위 요금으로 부산 하루를 직접 짭니다.","region":"부산 (시내 + 해안)","duration":"5~9시간","stopsCount":4,"rating":0,"reviewCount":0,"badges":["프라이빗 투어","일정 자유 변경","부산 숙소 픽업"],"tags":["private_tour","fully_customizable","hotel_pickup","hourly_rate"],"heroImage":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","thumbnail":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","priceLabel":"","shortCardDescription":"일행만 타는 전용 차량과 자격증 있는 기사 가이드가 부산 어디든 함께합니다. 추천 코스 세 가지 — 대표 명소를 도는 클래식 코스, 해동 용궁사와 스카이캡슐의 해안 코스, 원도심과 송도를 잇는 코스 — 중 하나로 시작해 스톱을 옮기고 빼고 더하면 그날은 일행의 하루가 됩니다. 숙소 픽업 포함, 5~9시간, 7인까지 차량당 한 가격."},"headlineLine1":"부산 시내","headlineLine2":"프라이빗 차량 전세","price":{"amountLabel":"160","currency":"USD","per":"vehicle","salePriceUsd":160},"hero":{"imageUrl":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","imagePosition":"center 45%","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"],"tagline":"바로 쓸 수 있는 부산 하루 세 가지에서 출발해, 기사 가이드가 그걸 다시 짜 드립니다 — 해안 절벽의 사찰, 스카이캡슐, 색칠한 언덕 마을, 어시장, 바다 위 스카이워크를 일행이 정말 원하는 하루로.","pills":["전용 차량","자격증 기사 가이드","숙소 픽업"],"meta":{"duration":"5~9시간","region":"부산 (시내 + 해안)","stops":"자유 구성","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"개요"},{"id":"itinerary","label":"일정"},{"id":"details","label":"상세 정보"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"리뷰"}],"glanceItems":[{"icon":"camera","label":"포토 밸류","value":"좋음","level":4},{"icon":"mountain","label":"경치 좋음","value":"좋음","level":4},{"icon":"footprints","label":"도보","value":"보통","level":3},{"icon":"cloud-rain","label":"우천 안전","value":"매우 좋음","level":5},{"icon":"users","label":"가족 적합","value":"매우 좋음","level":5},{"icon":"gauge","label":"균형","value":"유연함","level":5}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 1","alt":"코스 1: 부산 대표 명소 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 2","alt":"코스 1: 부산 대표 명소 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 3","alt":"코스 1: 부산 대표 명소 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 4","alt":"코스 1: 부산 대표 명소 — gallery image 4"},{"id":5,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 5","alt":"코스 1: 부산 대표 명소 — gallery image 5"},{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","caption":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — 1","alt":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — gallery image 1"},{"id":7,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","caption":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — 2","alt":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — gallery image 2"},{"id":8,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","caption":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — 3","alt":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — gallery image 3"},{"id":9,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 1","alt":"코스 3: 해안과 원도심 — gallery image 1"},{"id":10,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 2","alt":"코스 3: 해안과 원도심 — gallery image 2"},{"id":11,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 3","alt":"코스 3: 해안과 원도심 — gallery image 3"},{"id":12,"type":"photo","src":"/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 4","alt":"코스 3: 해안과 원도심 — gallery image 4"},{"id":13,"type":"photo","src":"/images/itinerary/gukje-market-arcade-sign-forest.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 5","alt":"코스 3: 해안과 원도심 — gallery image 5"},{"id":14,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 6","alt":"코스 3: 해안과 원도심 — gallery image 6"}],"itineraryStops":[{"number":1,"time":"8~9시간에 가장 잘 맞습니다","duration":"6개 스톱","name":"코스 1: 부산 대표 명소","category":"해안 사찰, 해안 공원, 추모 공원, 벽화 마을, 어시장","description":"부산 첫 방문에 어울리는 클래식한 하루로, **부산 대표 명소 데이투어**에서 가져왔습니다. 도시를 동에서 서로 가로지릅니다. 오전엔 절벽 위 해안 사찰, 점심 전엔 청사포와 블루라인파크 구간, 그다음 유엔기념공원의 고요, 감천의 색칠한 언덕, 마지막으로 살아 있는 자갈치 어시장입니다. \n\n전세로 타면 조인 투어의 역 집결 과정이 없어져 같은 스톱을 돌고도 시간이 남습니다. 그 여유는 대개 감천으로 갑니다 — 다들 거기서 더 있고 싶어 하니까요.","image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","/images/itinerary/jagalchi-harbor-sign.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","source":"atoc-korea"},{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-harbor-sign.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 1","alt":"코스 1: 부산 대표 명소 — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/cheongsapo-blue-line/chatgpt-image-2026-5-10-01-01-18.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 2","alt":"코스 1: 부산 대표 명소 — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 3","alt":"코스 1: 부산 대표 명소 — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 4","alt":"코스 1: 부산 대표 명소 — gallery image 4"},{"id":5,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"코스 1: 부산 대표 명소","caption":"코스 1: 부산 대표 명소 — 5","alt":"코스 1: 부산 대표 명소 — gallery image 5"}],"highlights":["해동 용궁사","청사포 & 해운대 블루라인파크","점심 식사 (부산 현지 식당)","재한유엔기념공원","감천문화마을","자갈치 어시장"],"timeUsed":["≈ 10:00 · 해동 용궁사 (75분)","≈ 11:30 · 청사포 & 해운대 블루라인파크 (75분)","≈ 13:00 · 점심 식사 (부산 현지 식당) (60분)","≈ 14:15 · 재한유엔기념공원 (60분)","≈ 15:30 · 감천문화마을 (75분)","≈ 17:15 · 자갈치 어시장 (60분)"],"whyOnRoute":"부산 첫날에 사진으로 봤던 그 장면들을, 되돌아가지 않는 순서로 보고 싶다면 가장 좋은 선택입니다. 감천을 빼면 걷는 양이 적고, 모든 스톱이 사계절 내내 유효합니다.","_poi_meta":{"match":"route_variant_no_single_poi","poi_key":"route_variant_highlights","imported_from":"busan-top-attractions-day-tour","imported_stop_count":6,"verified":true,"verified_date":"2026-08-07","note":"Recommended route imported from busan-top-attractions-day-tour at build time (owner instruction 2026-08-07). Stop names and times are that product''s own, per locale — re-run scripts/build-busan-city-charter-2026-08.mjs after re-coursing it."}},{"number":2,"time":"8시간에 가장 잘 맞습니다","duration":"7개 스톱","name":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","category":"해안 사찰, 유리 전망대, 스카이캡슐, 해수욕장, 벽화 마을 두 곳","description":"**소그룹 해안 사찰·스카이캡슐·문화마을 투어**에서 가져온, 사진 중심의 부산 하루입니다. 오전은 동부 해안에 머뭅니다. 해동 용궁사, 청사포 바다 위 유리 바닥의 다릿돌 전망대, 그리고 옛 철길을 따라 미포까지 가는 스카이캡슐입니다. \n\n오후에는 색칠한 두 언덕 마을로 넘어갑니다. 감천, 그리고 더 작고 조용한 닥밭골과 소망계단 모노레일입니다. \n\n스카이캡슐 티켓은 당일 구매이고 전세 요금에 포함되지 않습니다. 사람들이 가장 자주 걸리는 지점이 대기 줄인데, 그건 기사 가이드가 도와드립니다.","image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"}],"galleryItems":[{"id":6,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","caption":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — 1","alt":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — gallery image 1"},{"id":7,"type":"photo","src":"/images/tours/cheongsapo-blue-line/cheongsapo-sky-capsule-interior.webp","location":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","caption":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — 2","alt":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — gallery image 2"},{"id":8,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을","caption":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — 3","alt":"코스 2: 해안 사찰, 스카이캡슐, 벽화 마을 — gallery image 3"}],"highlights":["해동 용궁사","청사포 다릿돌전망대 (유리 스카이워크)","해운대 블루라인파크 스카이캡슐 (청사포→미포)","점심 (해운대/미포 인근 현지 식당)","해운대해수욕장","감천문화마을","닥밭골 벽화마을 & 소망계단 모노레일"],"timeUsed":["≈ 10:20 · 해동 용궁사 (60분)","≈ 11:40 · 청사포 다릿돌전망대 (유리 스카이워크) (40분)","≈ 12:30 · 해운대 블루라인파크 스카이캡슐 (청사포→미포) (50분)","≈ 13:25 · 점심 (해운대/미포 인근 현지 식당) (45분)","≈ 14:10 · 해운대해수욕장 (20분)","≈ 15:10 · 감천문화마을 (60분)","≈ 16:30 · 닥밭골 벽화마을 & 소망계단 모노레일 (30분)"],"whyOnRoute":"커플과 사진 찍는 분들께 가장 좋고, 여덟 곳을 빨리 도는 것보다 네 곳을 제대로 보고 싶은 분께 맞습니다. 감천의 경사만 빼면 걷는 부담도 가장 적습니다.","_poi_meta":{"match":"route_variant_no_single_poi","poi_key":"route_variant_skycapsule","imported_from":"busan-small-group-yonggungsa-skycapsule-gamcheon-tour","imported_stop_count":7,"verified":true,"verified_date":"2026-08-07","note":"Recommended route imported from busan-small-group-yonggungsa-skycapsule-gamcheon-tour at build time (owner instruction 2026-08-07). Stop names and times are that product''s own, per locale — re-run scripts/build-busan-city-charter-2026-08.mjs after re-coursing it."}},{"number":3,"time":"8~9시간에 가장 잘 맞습니다","duration":"10개 스톱","name":"코스 3: 해안과 원도심","category":"해안 사찰, 추모 공원, 시장 셋, 벽화 마을, 송도 전망 둘, 도심 타워","description":"세 코스 중 가장 빽빽하며, **부산 기항지 해안 버스투어**에서 가져왔습니다. 원래 크루즈 한 번의 기항 시간 안에 도시 전체를 보여주려고 만든 코스라, 부산에 하루밖에 없는 분께 딱 맞는 모양입니다. \n\n오전에 해동 용궁사와 유엔기념공원을 보고, 원도심을 짧게 짧게 이어갑니다. 자갈치, BIFF 광장, 국제시장, 그다음 감천, 바다 위로 뻗은 송도 구름산책로, 곶 위의 송도 스카이파크, 마지막으로 부산다이아몬드타워가 있는 용두산공원입니다. \n\n스톱 하나하나가 일부러 짧습니다 — 20~45분입니다. 천천히 보고 싶은 일행이라면 이 목록을 절반으로 줄이세요.","image":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","images":["/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","/images/itinerary/jagalchi-harbor-sign.webp","/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","/images/itinerary/gukje-market-arcade-sign-forest.webp","/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"],"imageCredits":[{"url":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","source":"atoc-korea"},{"url":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","source":"atoc-korea"},{"url":"/images/itinerary/jagalchi-harbor-sign.webp","source":"atoc-korea"},{"url":"/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","source":"atoc-korea"},{"url":"/images/itinerary/gukje-market-arcade-sign-forest.webp","source":"atoc-korea"},{"url":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","source":"atoc-korea"}],"galleryItems":[{"id":9,"type":"photo","src":"/images/tours/haedong-yonggungsa/haedong-yonggungsa-sunset-cliff.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 1","alt":"코스 3: 해안과 원도심 — gallery image 1"},{"id":10,"type":"photo","src":"/images/tours/un-memorial-cemetery/chatgpt-image-2026-5-10-12-32-23.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 2","alt":"코스 3: 해안과 원도심 — gallery image 2"},{"id":11,"type":"photo","src":"/images/itinerary/jagalchi-harbor-sign.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 3","alt":"코스 3: 해안과 원도심 — gallery image 3"},{"id":12,"type":"photo","src":"/images/tours/biff-square/biff-gwangbok-night-umbrellas.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 4","alt":"코스 3: 해안과 원도심 — gallery image 4"},{"id":13,"type":"photo","src":"/images/itinerary/gukje-market-arcade-sign-forest.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 5","alt":"코스 3: 해안과 원도심 — gallery image 5"},{"id":14,"type":"photo","src":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","location":"코스 3: 해안과 원도심","caption":"코스 3: 해안과 원도심 — 6","alt":"코스 3: 해안과 원도심 — gallery image 6"}],"highlights":["해동 용궁사","재한유엔기념공원","부산 현지 식당에서 점심 (자비 부담)","자갈치 어시장","BIFF 광장","국제시장","감천문화마을","송도 구름산책로","송도 스카이파크 (암남공원)","용두산공원 & 부산타워"],"timeUsed":["≈ 09:45 · 해동 용궁사 (50분)","≈ 11:05 · 재한유엔기념공원 (30분)","≈ 11:50 · 부산 현지 식당에서 점심 (자비 부담) (40분)","≈ 12:45 · 자갈치 어시장 (30분)","≈ 13:15 · BIFF 광장 (20분)","≈ 13:35 · 국제시장 (25분)","≈ 14:20 · 감천문화마을 (45분)","≈ 15:25 · 송도 구름산책로 (20분)","≈ 15:45 · 송도 스카이파크 (암남공원) (25분)","≈ 16:25 · 용두산공원 & 부산타워 (20분)"],"whyOnRoute":"부산이 긴 여행의 하루일 때, 세 곳을 제대로 보기보다 도시의 전체 윤곽을 보고 싶다면 이 코스입니다. 비 오는 날에도 가장 낫습니다 — 시장과 타워, 아케이드가 모두 실내입니다.","_poi_meta":{"match":"route_variant_no_single_poi","poi_key":"route_variant_coastal","imported_from":"busan-cruise-shore-excursion-bus-tour","imported_stop_count":10,"verified":true,"verified_date":"2026-08-07","note":"Recommended route imported from busan-cruise-shore-excursion-bus-tour at build time (owner instruction 2026-08-07). Stop names and times are that product''s own, per locale — re-run scripts/build-busan-city-charter-2026-08.mjs after re-coursing it."}},{"number":4,"time":"5~9시간 어느 옵션이든","duration":"예약한 시간이 허락하는 만큼","name":"코스 4: 직접 짜는 하루","category":"원하는 곳, 원하는 순서, 원하는 속도","description":"셋 중 하나를 꼭 고르실 필요는 없습니다. 목록을 보내 주세요 — 어디서 본 장소, 누가 추천한 식당, 시장, 절, 전망 좋은 카페, 가족이 가고 싶어 하는 가게 — 기사 가이드가 그걸 중심으로 하루를 짜고 예약하신 시간에 무엇이 들어가는지 솔직하게 알려 드립니다. \n\n코스를 섞는 건 흔한 일입니다. 코스 1의 해동 용궁사, 코스 2의 스카이캡슐, 코스 3의 송도, 점심은 원하는 곳에서. \n\n당일에도 바꿀 수 있습니다. 날씨가 나빠지거나, 어느 스톱이 생각보다 붐비거나, 그냥 지금 있는 곳에 더 있고 싶으면 말씀해 주세요. 예약한 시간 동안 차량은 일행 것이고, 다시 견적을 낼 일도 없습니다.","image":null,"images":[],"imageCredits":[],"galleryItems":[],"highlights":["가고 싶은 곳 목록을 보내 주시면 예약한 시간에 실제로 무엇이 들어가는지 알려 드립니다","코스 1·2·3의 스톱을 자유롭게 섞을 수 있습니다","한 곳에 더 머무는 것을 포함해 당일에도 계획을 바꿀 수 있습니다","김해공항 픽업·드롭, 경주 하루를 옵션으로 추가할 수 있습니다"],"timeUsed":["예약 시: 꼭 가고 싶은 곳을 보내 주시면 현실적인 순서를 확정해 드립니다","출발 24시간 전까지: 스톱 교체·삭제는 요금 변동 없음","당일: 기사 가이드와 속도와 순서를 조정","예약 시간 초과: 초과분은 시간당 요금이며 기사 일정에 따라 가능 여부가 달라집니다"],"whyOnRoute":"조인 투어 대신 전세를 타는 이유가 이것입니다. 정해진 일정은 그 자리를 산 모든 사람 사이의 타협이지만, 이 하루는 일행에게만 맞으면 됩니다.","_poi_meta":{"match":"route_variant_no_single_poi","poi_key":"route_variant_custom","verified":true,"verified_date":"2026-08-07","note":"Custom-route option — no fixed POIs by definition."}}],"routeFlowStops":[{"name":"숙소 픽업","type":"origin","theme":"Start"},{"name":"오전 스톱","type":"primary","theme":"Choose"},{"name":"점심 식사","type":"meal","theme":"Reset"},{"name":"오후 스톱","type":"primary","theme":"Continue"},{"name":"드롭오프","type":"return","theme":"End"}],"routePhases":[{"phase":1,"title":"출발점이 될 코스를 고릅니다","summary":"아래 추천 코스 셋은 저희가 실제로 운행하는 부산 투어에서 그대로 가져온 것으로, 실제 스톱 순서와 시각이 그대로 들어 있습니다. 그대로 타셔도 되고 밑그림으로 쓰셔도 됩니다."},{"phase":2,"title":"원하는 대로 바꿉니다","summary":"스톱을 빼거나, 다른 데서 본 곳을 넣거나, 점심을 길게 하거나, 오후 내내 한 곳에 있어도 됩니다. 요금은 차량당·시간당이라 일정을 바꿔도 다시 견적을 내지 않습니다."},{"phase":3,"title":"필요한 곳에서 끝냅니다","summary":"숙소로 돌아오거나, 유료 옵션으로 김해공항이나 부산역에서 마칠 수 있습니다. 경주는 하루 연장 옵션으로 추가할 수 있습니다."}],"routeShapeIntro":{"title":"이미 검증된 코스에서 출발해, 내 하루로 바꾸세요","body":"아래 세 코스는 예시가 아닙니다. 각각 저희가 실제로 운행하는 부산 투어의 일정 그 자체이고, 스톱 순서·시각·소요 시간을 그 상품에서 그대로 가져왔습니다. 그래서 무엇을 바꾸기 전에 그런 모양의 하루가 실제로 어떻게 맞물리는지 먼저 보실 수 있습니다. 대부분은 하나를 고르고 두세 곳만 바꿉니다. 세 코스의 어느 스톱이든 다른 코스로 옮길 수 있습니다."},"whyTourWorks":{"bestFor":["가족과 삼대 여행 — 차량 한 대로, 환승도 역 사이를 걷는 일도 없습니다","정해진 하루를 따라가기보다 직접 정하고 싶은 커플과 소규모 일행","부산에 하루뿐이라 민주적인 일정보다 효율적인 동선이 필요한 분","정해진 단체 투어가 맞춰 줄 수 없는 속도·거동·식사 조건이 있는 분","도착일이나 출발일에 반나절을 버리는 대신 김해공항 옵션을 쓰고 싶은 분"],"lessIdealFor":["예산이 빠듯한 1인 여행자 — 인원당 요금의 조인 투어가 더 저렴합니다","가이드가 이끄는 단체 출발의 짜임새와 해설을 원하는 분","14인을 넘는 일행 — 차량 두 대가 아니라 버스가 필요합니다"],"routeLogicSections":[{"title":"왜 버스 좌석이 아니라 전세인가","icon":"highlight","iconBg":"bg-amber-50/80","iconColor":"text-amber-600","items":[{"label":"부산은 넓게 흩어져 있습니다","detail":"해안 사찰은 북동쪽, 감천은 서쪽, 송도는 더 남쪽이고 그 사이에 다리와 해안도로, 언덕, 원도심의 일방통행이 있습니다. 전용 차량은 그 이동을 비용이 아니라 하루의 일부로 만듭니다."},{"label":"바꿔도 다시 견적을 내지 않습니다","detail":"스톱을 빼거나 더하거나, 점심을 길게 하세요. 요금은 이용 시간과 차량 대수로 정해지므로 일정을 바꿔도 청구서는 그대로입니다."},{"label":"시계는 일행 것입니다","detail":"07:00에 출발해 해동 용궁사를 거의 전세 내듯 보거나, 늦잠을 잤으니 11:00에 시작하거나. 단체 출발로는 둘 다 안 됩니다."}]},{"title":"요금이 정해지는 방식","icon":"ticket","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"차량당, 시간당","detail":"5~9시간, US$160~US$255입니다. 1인부터 7인까지 같은 금액이라, 다섯 명이 오면 한 사람 몫은 두 명이 나눌 때의 5분의 2 수준이 됩니다."},{"label":"8인 이상은 차량 두 대","detail":"이 상품에는 더 큰 단일 차량이 없습니다. 8인 이상은 차량 두 대로 견적되며 같은 시간 기준 두 배 요금이고, 함께 이동합니다."},{"label":"옵션은 숨기지 않고 명시합니다","detail":"김해공항 픽업 또는 드롭 US$35, 경주 하루 US$55, 9시간 초과 1시간당 US$35. 입장료와 식사는 선택하신 스톱에서 직접 결제하십니다."}]},{"title":"기사 가이드가 맡는 일","icon":"shield-check","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","items":[{"label":"주차, 티켓, 대기 줄","detail":"주차는 포함이고 기사가 처리합니다. 티켓 대기 줄이 병목인 곳 — 특히 스카이캡슐 — 에서는 기사 가이드가 대신 서고 일행은 그늘에서 기다리시면 됩니다."},{"label":"가능한 계획을 미리 말합니다","detail":"보내신 목록이 예약한 시간에 안 들어가면 당일 16시에 알게 되는 게 아니라 그전에 말씀드립니다. 일정을 미리 확정하는 이유가 그 솔직함입니다."},{"label":"일행에게 맞는 점심","detail":"무엇을 드시는지 알려 주세요 — 해산물, 돼지국밥, 채식, 할랄, 아이들을 위한 안 매운 것 — 이미 가 있는 곳 근처에서 점심을 고릅니다."}]}]},"practicalAccordionItems":[{"id":"pickup","title":"픽업과 드롭오프, 이용 시간 계산 방식","preview":"픽업은 부산 시내 어디든 숙소 앞에서, 원하시는 시각에 시작합니다 — 서면, 해운대, 남포동, 부산역과 그 주변 지역입니다. 외곽 주소도 대개 가능하며 예약 시 확인해 드립니다.","content":["픽업은 부산 시내 어디든 숙소 앞에서, 원하시는 시각에 시작합니다 — 서면, 해운대, 남포동, 부산역과 그 주변 지역입니다. 외곽 주소도 대개 가능하며 예약 시 확인해 드립니다.","예약하신 시간은 확정된 픽업 시각에 시작해 드롭오프에 끝납니다. 첫 관광지나 마지막 관광지 기준이 아닙니다. 스톱 사이 이동도 하루의 일부입니다.","드롭오프는 부산 어디든 가능합니다. 숙소로 돌아오셔도 되고, 다음 숙소나 부산역, 저녁 식사 장소에서 마치셔도 됩니다.","김해국제공항 픽업 또는 드롭은 유료 옵션으로 가능합니다 — 옵션 항목을 확인해 주세요."]},{"id":"rates","title":"이용 시간과 요금","preview":"인원당이 아니라 차량당 한 가격입니다: 5시간 US$160 · 6시간 US$185 · 7시간 US$205 · 8시간 US$225 · 9시간 US$255, 1~7인 기준.","content":["인원당이 아니라 차량당 한 가격입니다: 5시간 US$160 · 6시간 US$185 · 7시간 US$205 · 8시간 US$225 · 9시간 US$255, 1~7인 기준.","1인이든 7인이든 요금은 같습니다. 차량과 기사 가이드에 대한 요금이라, 인원이 많을수록 한 사람이 부담하는 몫은 줄어듭니다.","8인 이상은 차량이 한 대 더 필요하며, 같은 시간 기준으로 위 금액의 두 배입니다.","9시간을 넘는 시간은 시간당 추가 요금이며 기사 일정에 따라 가능 여부가 달라집니다. 당일이 아니라 예약 시에 문의해 주세요."]},{"id":"addons","title":"추가 옵션: 공항, 경주, 시간 연장","preview":"김해공항 픽업 또는 드롭 US$35, 경주 하루 US$55, 9시간 초과 1시간당 US$35입니다.","content":["김해공항 픽업 또는 드롭 US$35, 경주 하루 US$55, 9시간 초과 1시간당 US$35입니다.","공항 이동: 도착일이나 출발일에 유용합니다. 짐을 찾아 그대로 부산에서 하루를 보내고, 숙소로 되돌아가지 않고 공항에서 마칠 수 있습니다.","경주: 신라의 옛 수도로 부산에서 차로 약 70분입니다. 전세에 붙이면 온전한 하루 일정이 됩니다 — 불국사, 대릉원의 왕릉, 황리단길 — 제대로 보려면 9시간 이상이 필요합니다.","모든 옵션은 예약 시에 정합니다. 기사의 하루 일정이 그에 맞춰 짜여야 하기 때문입니다."]},{"id":"customize","title":"일정 변경","preview":"세 코스는 정해진 상품이 아니라 출발점입니다. 어느 스톱이든 추가·삭제·순서 변경·교체할 수 있습니다.","content":["세 코스는 정해진 상품이 아니라 출발점입니다. 어느 스톱이든 추가·삭제·순서 변경·교체할 수 있습니다.","예약 시 또는 출발 24시간 전까지 변경 사항을 보내 주시면, 기사 가이드가 바뀐 순서를 확정하고 무엇이 들어가고 무엇이 안 들어가는지 솔직하게 알려 드립니다.","당일에도 날씨나 혼잡, 또는 그냥 한 곳에 더 있고 싶다는 이유로 순서를 바꿀 수 있습니다.","일정을 바꿔도 요금은 그대로입니다. 결제 금액은 이용 시간과 차량 대수로 정해지며, 어디를 가는지로 정해지지 않습니다."]},{"id":"vehicle","title":"차량, 기사, 정원","preview":"1~3인은 세단 또는 SUV, 4~7인은 중형 밴입니다. 차량은 일행만 이용하며 다른 예약과 함께 타지 않습니다.","content":["1~3인은 세단 또는 SUV, 4~7인은 중형 밴입니다. 차량은 일행만 이용하며 다른 예약과 함께 타지 않습니다.","기사는 자격증과 보험을 갖추고 있으며 영어가 가능합니다. 중국어 가능 기사는 예약 시 요청하면 대개 배정 가능하고, 그 외 언어는 일정에 따라 다릅니다.","카시트는 예약 시 아이 나이를 알려 주시면 무료로 준비해 드립니다.","공항 이동 시 짐은 문제없지만, 정원을 꽉 채운 일행에 대형 캐리어까지 전부 실리지는 않습니다. 캐리어 개수를 알려 주시면 맞는 차량을 보내 드립니다."]},{"id":"inclusions","title":"포함 사항과 현장 결제 사항","preview":"포함: 일행 전용 차량과 기사 가이드 · 부산 내 픽업과 드롭오프 · 통행료, 주차료, 유류비 · 예약 수수료.","content":["포함: 일행 전용 차량과 기사 가이드 · 부산 내 픽업과 드롭오프 · 통행료, 주차료, 유류비 · 예약 수수료.","불포함: 선택하신 스톱의 입장료와 탑승권 · 식사와 음료 · 코스 2의 스카이캡슐 티켓 · 개인 경비 · 팁 · 여행자 보험.","이 코스들의 입장료는 부담이 크지 않고, 좋은 스톱 상당수가 무료입니다 — 감천과 닥밭골 마을, 유엔기념공원, 해운대해수욕장, 시장들, 송도 스카이워크 모두 입장료가 없습니다.","줄을 서는 편이 빠른 곳에서는 기사 가이드가 대신 구매해 드릴 수 있고, 당일 현금으로 정산하시면 됩니다."]},{"id":"policy-surcharge-cancellation","title":"할증, 취소 규정, 이 전세가 맞는 분","preview":"시간 외 할증: 07:00 이전 출발이나 20:00 이후 종료는 시간당 할증이 붙고 당일 결제합니다.","content":["시간 외 할증: 07:00 이전 출발이나 20:00 이후 종료는 시간당 할증이 붙고 당일 결제합니다.","취소: 출발 24시간 전까지 무료 취소입니다. 24시간 이내에는 환불되지 않습니다.","경주 외에 부산을 벗어나는 목적지는 별도 견적입니다. 예약 전에 문의해 주세요.","이 전세는 하루를 직접 정하고 싶은 일행에게 맞습니다. 정해진 대로 다니고 더 저렴한 편이 낫다면, 코스 1과 코스 3을 인원당 요금으로 운행하는 조인 데이투어가 있습니다."]}],"practicalWeatherStatic":{"summary":"부산은 사계절이 뚜렷한 고온다습한 아열대성 기후입니다. 크루즈 시즌은 봄(3~5월)과 가을(9~11월)에 집중되며, 두 계절 모두 기온 12~25°C에 강수량이 적어 쾌적합니다. 여름(6~8월)은 덥고 습하며 간헐적인 장마가 내릴 수 있고, 겨울(12~2월)은 서늘하고 바람이 강합니다.","advice":"봄·가을에는 겹쳐 입을 수 있는 레이어링 의류, 여름에는 자외선 차단 용품과 가벼운 우비, 겨울에는 태종대 해안 절벽을 위한 따뜻한 코트와 장갑을 준비하세요."},"seasonalVariations":[{"season":"봄 (3~5월)","summary":"달맞이길, 용두산공원, 광안리해수욕장에서 3월 말~4월 초에 벚꽃이 절정을 이룹니다. 기온 12~22°C로 쾌적하며, 가벼운 레이어링이 적합합니다.","swaps":"벚꽃 주간에는 달맞이길 드라이브와 광안리 추가 정차를 요청하세요. 코스 1·2에서 몇 분이면 닿습니다."},{"season":"여름 (6~8월)","summary":"기온 25~32°C의 덥고 습한 날씨로, 6~7월에는 장마가 올 수 있습니다. 일몰이 늦기 때문에 하루 일정 마지막에 해안 추가 정류장을 넣기에 좋습니다.","swaps":"더운 오후에는 감천을 오전으로 옮기고, 한낮에는 냉방이 되는 스카이캡슐이나 지붕 있는 시장을 넣으세요."},{"season":"가을 (9~11월)","summary":"한국 여행 최적의 날씨 — 기온 15~25°C, 낮은 습도, 맑고 풍성한 빛. 크루즈 시즌의 성수기입니다.","swaps":"가을에는 세 코스 모두 그대로 좋습니다. 9시간으로 예약하신다면 단풍철 범어사를 더할 만합니다."},{"season":"겨울 (12~2월)","summary":"기온 0~10°C의 서늘하고 바람 강한 날씨이지만, 크루즈 운항은 계속됩니다. 해안 정류장은 차갑고 맑아 색다른 아름다움을 선사합니다.","swaps":"겨울에는 해가 일찍 지므로 야외 전망을 앞에 두고, 시장이나 타워, 아케이드 같은 실내로 마무리하세요."}],"bookingTrustItems":[{"icon":"user-check","title":"자격증 있는 현지 기사 가이드","detail":"모든 기사는 자격증과 보험을 갖추고 영어가 가능하며, AtoC Korea 부산 파트너 네트워크에서 검증합니다.","body":"AtoC Korea 부산 파트너 네트워크에서 검증한 자격증 있는 현지 기사 가이드입니다. 투어라는 이름만 붙인 호출 차량이 아닙니다."},{"icon":"shield-check","title":"어떤 코스든 요금은 하나","detail":"차량당·시간당 요금이라 스톱을 더하거나 빼거나 순서를 바꿔도 결제 금액은 달라지지 않습니다.","body":"어떤 코스든 요금은 하나입니다. 총액은 예약한 시간과 차량 대수로 정해지며, 스톱 변경은 금액에 영향을 주지 않습니다."},{"icon":"clock","title":"24시간 전까지 무료 취소","detail":"픽업 24시간 전까지 무료 취소입니다. 날씨에 좌우되는 부산 하루에는 중요한 조건입니다.","body":"픽업 24시간 전까지 무료 취소입니다. 비로 하루가 통째로 날아갈 수 있는 해안 도시에서는 이게 중요합니다."}],"bookingSupportSteps":[{"step":1,"title":"온라인 예약","detail":"날짜와 이용 시간을 고르세요. 지금 예약하고 나중에 결제합니다.","description":"온라인으로 예약하고 날짜와 이용 시간을 선택하시면 즉시 확정됩니다."},{"step":2,"title":"숙소를 알려 주세요","detail":"숙소와 원하시는 출발 시각을 보내 주시면 24시간 안에 픽업을 확정합니다.","description":"픽업 장소와 시각을 확정할 수 있도록 숙소와 원하시는 출발 시각을 보내 주세요."},{"step":3,"title":"코스를 고르거나 직접 짜세요","detail":"세 코스 중 하나를 고르거나 직접 목록을 보내 주세요 — 출발 24시간 전까지.","description":"추천 코스 셋 중 하나를 고르거나 직접 스톱 목록을 보내 주시면, 예약한 시간에 무엇이 들어가는지 확정해 드립니다."},{"step":4,"title":"기사 정보 안내","detail":"기사 이름, 차량 번호, 연락처를 전날 저녁에 보내 드립니다.","description":"기사 이름과 차량 번호, 연락 가능한 전화번호를 전세 전날 저녁에 보내 드립니다."},{"step":5,"title":"숙소에서 만납니다","detail":"약속한 시각에 기사 가이드가 로비 또는 입구에서 기다립니다.","description":"확정된 시각에 숙소에서 기사 가이드를 만나시면 그때부터 예약한 시간이 시작됩니다."}],"staticQuestions":[{"id":"capacity","question":"몇 명까지 가능하고, 인원에 따라 요금이 달라지나요?","answer":"1~7인이 차량 한 대에 같은 요금으로 탑승합니다. 1~3인은 세단이나 SUV, 4~7인은 중형 밴입니다. 인원에 따라 요금이 달라지지 않아서, 여섯 명 가족이 커플과 같은 총액을 냅니다. 8인부터는 차량을 한 대 더 보내며 같은 시간 기준으로 1대 요금의 두 배입니다."},{"id":"hours","question":"이용 시간은 어떻게 계산하고, 초과하면 어떻게 되나요?","answer":"확정된 픽업 시각부터 드롭오프까지가 이용 시간이며 스톱 사이 이동도 포함됩니다. 전세는 5·6·7·8·9시간 단위로 판매합니다. 9시간을 넘기고 싶으시면 1시간당 US$35이고, 기사 일정에 달려 있어 당일이 아니라 예약 시에 정해야 합니다."},{"id":"customise","question":"추천 코스를 바꿀 수 있나요?","answer":"네, 그러라고 만든 상품입니다. 세 코스는 저희가 이미 운행 중인 부산 투어의 실제 일정을 출발점으로 제공한 것입니다. 어느 스톱이든 추가·삭제·순서 변경·교체할 수 있고, 코스 간에 섞거나 완전히 다른 목록을 보내셔도 됩니다. 변경은 무료이며 출발 24시간 전까지 보내 주시면 되고, 당일에도 날씨나 혼잡에 따라 순서를 바꿀 수 있습니다."},{"id":"airport","question":"김해공항에서 픽업하거나 공항에 내려 줄 수 있나요?","answer":"네, 편도 기준 US$35의 유료 옵션입니다. 도착일이나 출발일에 많이들 이렇게 씁니다. 짐을 찾아 그대로 예약한 시간만큼 부산을 보고, 숙소로 되돌아가지 않고 공항에서 마치는 방식입니다."},{"id":"gyeongju","question":"부산 대신 경주에 갈 수 있나요?","answer":"네, US$55 연장 옵션입니다. 경주는 부산에서 차로 약 70분이라 반나절이 아니라 하루 일정이 됩니다. 보통 불국사, 대릉원 왕릉 공원, 황리단길로 짭니다. 여유 있게 보시려면 9시간 이상으로 예약해 주세요."},{"id":"included","question":"입장료와 점심이 포함인가요?","answer":"아닙니다. 전세 요금은 차량, 기사 가이드, 유류비, 통행료, 주차료를 포함합니다. 입장료와 스카이캡슐 같은 탑승권, 식사는 선택하신 스톱에서 직접 결제하십니다. 이 코스들의 좋은 스톱 상당수는 입장료가 없습니다 — 벽화 마을 두 곳, 유엔기념공원, 시장들, 송도 스카이워크가 그렇습니다."},{"id":"language","question":"기사 가이드는 어떤 언어를 하나요?","answer":"모든 전세에서 영어가 가능합니다. 중국어 가능 기사 가이드는 예약 시 요청하면 대개 배정됩니다. 그 외 언어는 해당 날짜의 배차 상황에 따라 다르니, 예약 후가 아니라 예약 전에 문의해 주세요."}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"날짜와 이용 시간, 인원을 선택하면 실시간 예약 가능 여부를 확인하고 예약을 완료할 수 있습니다.","price":{"amountLabel":"160","currency":"USD","per":"vehicle","salePriceUsd":160}},"pickup_dropoff":{"type":"hotel_pickup","meeting_points":[{"name":"부산 시내 숙소","time":"원하시는 출발 시각, 보통 07:00~11:00","note":"부산 시내 어디든 숙소 앞에서 픽업합니다 — 서면, 해운대, 남포동, 부산역과 그 주변 지역. 외곽 주소도 대개 가능하며 예약 시 확인해 드립니다."}],"dropoff_points":[{"name":"부산 내 원하시는 장소","approx_time":"예약하신 이용 시간 종료 시점","note":"숙소로 돌아오셔도 되고, 숙소를 옮기신다면 다른 호텔, 부산역, 또는 저녁 식사 장소에서 마치셔도 됩니다. 김해공항은 유료 옵션으로 가능합니다."}],"hotel_pickup_available":true,"notes":["예약하신 이용 시간은 확정된 픽업 시각부터 드롭오프까지이며, 스톱 사이 이동도 포함됩니다.","김해국제공항 픽업 또는 드롭은 US$35가 추가되며 예약 시에 정합니다."]},"matching_profile":{"profile_version":1,"is_active":true,"product_id":"busan-private-car-charter-city-tour","product_type":"private","route_type":"customizable","destination_region":"busan_city","region_type":"busan_city","vehicle_type":"private_vehicle","duration_hours":8,"region_tags":["busan","busan_central","busan_eastern","busan_western"],"theme_tags":["private_charter","customizable_route","city_highlights","coastal","cultural"],"poi_tags":["haedong_yonggungsa","gamcheon_culture_village","cheongsapo_blue_line_park","jagalchi_market","un_memorial_cemetery","songdo_skywalk"],"pace_level":0.6,"walking_level":0.5,"scenic_level":0.85,"photo_level":0.85,"culture_level":0.8,"relax_level":0.55,"first_time_fit":0.95,"family_fit":0.85,"senior_fit":0.9,"couple_fit":1,"solo_traveler_fit":0.5,"active_traveler_fit":0.65,"adult_family_fit":0.85,"family_with_teens_fit":0.85,"young_kids_fit":0.65,"senior_active_fit":0.85,"senior_general_fit":0.9,"mobility_friendly_fit":0.75,"stroller_fit":0.5,"one_day_fit":0.8,"same_day_flight_fit":0.8,"rain_fit":0.65,"value_for_money_fit":0.7,"iconic_landmark_fit":0.85,"cafe_fit":0.4,"food_fit":0.65,"nature_fit":0.55,"beach_fit":0.4,"nightlife_fit":0.1,"shopping_fit":0.55,"no_shopping_fit":0.55,"local_culture_fit":0.8,"storytelling_fit":0.85,"unesco_fit":0.1,"intangible_heritage_fit":0.4,"indoor_ratio":0.15,"weather_sensitivity":0.7,"comfort_level":0.85,"budget_fit":0.2,"premium_fit":0.85,"small_group_fit":0,"private_fit":0.95,"bus_fit":0.1,"price_band":"mid_to_premium","pickup_base":"busan_hotel","return_time_band":"late_afternoon","duration_band":"5h-9h","min_recommended_age":0,"hard_constraints":["Private charter — 1 to 7 guests in one vehicle. 8 or more guests are quoted as two vehicles.","Sold by the hour: 5 to 9 hours. Each hour past 9 is a paid extension, subject to driver availability.","Gimhae Airport pickup or drop-off and the Gyeongju extension are paid add-ons, not included in the base hours."],"walking_notes":"Door-to-door by vehicle between stops. The only sustained walking is inside a chosen stop — Gamcheon Culture Village is a steep hillside village, and market stops are flat but crowded.","keywords":["Busan private car charter","Busan private day tour","Busan hotel pickup private tour","Busan chauffeur day tour","Busan to Gyeongju private car"],"synonym_hints":["private taxi","private driver","shore excursion","cruise day tour","private guide","customized itinerary","cruise terminal pickup"],"seasonality":{"spring":0.9,"summer":0.85,"autumn":0.95,"winter":0.7},"pickup_base_normalized":"busan_central_pickup","vehicle_type_legacy":"private_sedan_or_van","anchor_poi_keys":["haedong_yonggungsa","gamcheon_culture_village","cheongsapo_blue_line_park","jagalchi_market","un_memorial_cemetery","songdo_skywalk"],"private_tour_fit":1,"shared_tour_fit":0,"customizable_route_fit":0.6,"flexibility_fit":0.85,"solo_fit":0.5,"family_with_kids_fit":0.95,"small_party_fit":1,"lar