  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"busan-private-car-charter-city-tour","locale":"zh","product_id":"busan-private-car-charter-city-tour","seo":{"pageTitle":"釜山私人包车（5–9 小时）| AtoC Korea","metaDescription":"含英语持证司机导游与酒店接送的釜山私人包车。可选三条推荐路线，也可自行安排行程。5 至 9 小时，7 人以内按车计价，可加金海机场接送与庆州延伸。","title":"釜山私人包车（司机导游随行）| AtoC Korea","description":"含酒店接送与持证司机导游的釜山按小时私人包车。推荐路线直接取自我们正在运营的三条釜山线路，可随您调整。","primaryKeywords":["釜山私人包车","釜山包车一日游","釜山酒店接送包车","釜山司机导游","釜山庆州私人包车"],"ogImage":"https://www.atockorea.com/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"},"catalog_card":{"slug":"busan-private-car-charter-city-tour","title":"釜山私人包车","subtitle":"专属车辆与持证司机导游到酒店接您，按小时计费，釜山这一天由您自己安排。","region":"釜山（市区 + 海岸）","duration":"5–9 小时","stopsCount":4,"rating":0,"reviewCount":0,"badges":["私人包团","行程自由调整","釜山酒店接送"],"tags":["private_tour","fully_customizable","hotel_pickup","hourly_rate"],"heroImage":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","thumbnail":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","priceLabel":"","shortCardDescription":"只属于您一行人的专车与持证司机导游，带您走遍釜山。可从三条推荐路线出发 — 经典的热门景点线、海东龙宫寺与天空胶囊的海岸线、老城区与松岛的环线 — 再把停留点调整、删减或增加，这一天就完全是您的。含酒店接送，5 至 9 小时，7 人以内按车计价。"},"headlineLine1":"釜山市区","headlineLine2":"私人包车","price":{"amountLabel":"160","currency":"USD","per":"vehicle","salePriceUsd":160},"hero":{"imageUrl":"/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp","imagePosition":"center 45%","images":["/images/tours/gamcheon-culture-village/kakaotalk-20260510-222952680-01.webp"],"tagline":"三条现成的釜山一日行程作起点，司机导游会把它们重新排列 — 海崖上的寺庙、天空胶囊、彩绘山城、鱼市、海上天空步道 — 拼成您真正想要的那一天。","pills":["专属车辆","持证司机导游","酒店接送"],"meta":{"duration":"5–9 小时","region":"釜山（市区 + 海岸）","stops":"自由组合","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"概览"},{"id":"itinerary","label":"行程"},{"id":"details","label":"详情"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"评价"}],"gl