-- 3) default offer — the cheapest rate-card cell, so the catalogue, the page
--    and checkout all state the same number.
INSERT INTO public.tour_product_offers (tour_product_page_id, label, amount_minor, currency, stripe_price_id, is_active, is_default)
SELECT p.id, 'Busan city private charter (5 hours, 1–7 pax)', 16000, 'USD', NULL, TRUE, TRUE
  FROM public.tour_product_pages p
 WHERE p.slug = 'busan-private-car-charter-city-tour' AND p.locale = 'en'
   AND NOT EXISTS (SELECT 1 FROM public.tour_product_offers o WHERE o.tour_product_page_id = p.id);

COMMIT;

